import { useDispatch, useSelector } from "react-redux";
import { useParams } from "react-router-dom";
import { productSelector } from "../../store/selectors/productSelectors";
import { useEffect } from "react";
import { getProductsMiddleWare } from "../../store/store";
import { deleteProduct } from "../../store/actions/productActions";

import style from "./EachProduct.module.css";

const EachProduct = () => {
  const { id } = useParams();
  const dispatch = useDispatch();
  const data = useSelector(productSelector);
  useEffect(() => {
    dispatch(getProductsMiddleWare());
  }, []);

  const filteredData = data.filter((elm) => {
    return elm.id.toString() === id;
  });

  return (
    <div className={style.main}>
      {/* <p>{filteredData[0]?.title}</p>
      <p>{filteredData[0]?.price}</p> */}
        <div className={style.product}>
          <button className={style.edit}>
            <img
              src="https://static-00.iconduck.com/assets.00/edit-icon-1024x1024-u3a8q4uh.png"
              alt="edit"
              className={style.editImg}
            />
          </button>
          <button
            className={style.del}
            onClick={dispatch(deleteProduct(elm.id, filteredData))}
          >
            X
          </button>
          <div className={style.imgDiv}>
            <img
              src={filteredData[0]?.images[0]}
              alt="photoOfProducts"
              className={style.img}
            />
            <img
              src={filteredData[0]?.images[1]}
              alt="photoOfProducts"
              className={style.img}
            />
            <img
              src={elm.images[2]}
              alt="photoOfProducts"
              className={style.img}
            />
          </div>
          <div className={style.details}>
            <h2>{elm.title}</h2>
            <p>{elm.description}</p>
            <h4>$ {elm.price}</h4>
          </div>
        </div>
    </div>
  );
};

export default EachProduct;
